\overrightarrow{AD} &= \mathbf{A} - \mathbf{D} = \mathbf{A} - \frac{\mathbf{B} + \mathbf{C} - 2 \mathbf{A}}{2} = \frac{3 \mathbf{A} - \mathbf{B} - \mathbf{C}}{2}, \\
\overrightarrow{BE} &= \mathbf{B} - \mathbf{E} = \mathbf{B} - \frac{2 \mathbf{A} + \mathbf{C} - \mathbf{B}}{2} = \frac{-2 \mathbf{A} + 3 \mathbf{B} - \mathbf{C}}{2}, \\
\overrightarrow{CF} &= \mathbf{C} - \mathbf{F} = \mathbf{C} - \frac{2 \mathbf{A} + \mathbf{B} - \mathbf{C}}{2} = \frac{-2 \mathbf{A} - \mathbf{B} + 3 \mathbf{C}}{2}.
\end{aligned}
\]Thus,
